(6972884, 1051097, 62318, '<td valign="top">The light on the subject (hands) does it for me. But I feel the compositional elements (cars) on the left just pull me away from the shot. Not enough to reduce you from a score of 9, but something that prevents perfection.</td>', 'The light on the subject (hands) does it for me. But I feel the compositional elements (cars) on the left just pull me away from the shot. Not enough to reduce you from a score of 9, but something that prevents perfection.', '2013-02-05 23:56:39.000000', NULL, 1),
(6972885, 1051594, 152252, '<td valign="top">One of my top 3. Amazing. 10</td>', 'One of my top 3. Amazing. 10', '2013-02-05 23:56:48.000000', NULL, 1),
(6972887, 1051559, 62318, '<td valign="top">Okay--you know how to frame a shot, but this is more... it is a mastery of the moment. It''s using the correct color palette; it is using a sense of depth; and mostly--it is a touch of humanity. Nicely done.</td>', 'Okay--you know how to frame a shot, but this is more... it is a mastery of the moment. It''s using the correct color palette; it is using a sense of depth; and mostly--it is a touch of humanity. Nicely done.', '2013-02-05 23:57:17.000000', NULL, 1),
